		// settings file Gradle finds first when started there. `-p` is the spelling for that.
		return searchVerifySuiteCommand(
			wrapperDir,
			"./gradlew -p "+shellQuotePath(relative)+" test",
			manifest+" + "+wrapperPath+" + "+settingsPath,
