	// declares it — the documented spelling, `gradle :subproject:taskName`.
	return searchVerifySuiteCommand(
		wrapperDir,
		"./gradlew "+shellQuote(project+":test"),
		manifest+" + "+wrapperPath+" + "+settingsPath,
	)
}

